/*
 * ===========================================================================
 *  EVERY ONEPAGE SQL PART FROM THE LAST 14 DAYS, IN ONE PASTE
 * ===========================================================================
 * For the Supabase SQL editor: paste the whole file and Run. Made from
 * supabase/sql/run-now, the parts that create or change a OnePage table
 * (onepages, onepage_leads, onepage_views, onepage_clicks,
 * onepage_slug_history, onepage_integrations, onepage_integration_sends),
 * the onepage-assets and avatars buckets and their policies, or a function
 * or trigger that writes them. Each part is copied as it is in run-now, and
 * each was written to be run again safely (IF NOT EXISTS, CREATE OR REPLACE,
 * DROP ... IF EXISTS, and a NOTICE where a table it needs is not there).
 *
 * Dated by git log: this clone's history starts on 2026-10-26, and every
 * part below was added between then and 2026-10-28, all inside the 14 days
 * to 2026-10-28. Parts that only name 'onepage' as a label (an analytics
 * source, an email kind) are left out: 21, 46, 60, 61, 66, 328. So are the
 * two whole-database checks, 00 and 99.
 *
 * In run-now's order, except 90 and 91, which run-now itself says run last:
 * 90 replaces the storage policies and needs the owner of storage.objects.
 * If it stops with "must be owner of table objects", everything above it has
 * already run; see supabase/sql/run-now/README.md, Route 1, for 90.
 *
 * THE PROFILE PHOTO. Saving a cropped photo in the OnePage editor writes
 * profiles.avatar_url through app/api/account/avatar, and then every copy of
 * it: onepages.avatar_url and its published copy, creators.avatar_url, the
 * creator page header. The parts it leans on are 44 and 53 (the trigger that
 * moves the copies, which never fails the save) and 90 (the avatars bucket's
 * owner folder policies; the upload itself needs them). The editor now says
 * which step failed and, for a database refusal, its code (lib/onepage/
 * photo-save, lib/account/avatar-save): 42501 is a refused write, 42703 a
 * column this database does not have.
 *
 * Parts included:
 *   16_storage_buckets.sql                   2026-10-26  the onepage-assets bucket (public, pictures and videos, size limit) beside the other picture buckets
 *   18_storage_cleanup_functions.sql         2026-10-26  the storage passes that read onepage-assets (and avatars) for new and unused files
 *   25_analytics_speed.sql                   2026-10-26  indexes on onepage_views, onepage_clicks and onepage_leads for the stats
 *   43_onepage_forget_deleted_product.sql    2026-10-26  a deleted product leaves every OnePage it sat on (trigger on products, function over onepages)
 *   44_profile_identity_follows.sql          2026-10-26  the profile's name and photo follow into onepages (title, avatar_url, published copy, SEO title)
 *   53_one_profile_photo.sql                 2026-10-26  one profile photo: every copy, onepages.avatar_url included, takes the profile's photo
 *   54_onepage_address_any_case.sql          2026-10-26  onepages.slug unique whatever its case
 *   57_onepage_share_image.sql               2026-10-26  onepages share image columns and their check
 *   58_onepage_old_addresses.sql             2026-10-26  onepage_slug_history: an old address keeps working after a rename
 *   70_public_upload_safety.sql              2026-10-26  a size ceiling on onepage-assets and the recent uploads list
 *   165_columns_production_has.sql           2026-10-26  onepages.seller_id and the other columns the app reads
 *   281_onepage_leads_country.sql            2026-10-26  onepage_leads.country
 *   282_onepage_media_uploads.sql            2026-10-26  onepage-assets takes 2 GB videos and every type the editor sends; the owner folder policies
 *   315_onepage_integrations.sql             2026-10-28  onepage_integrations: the tools a OnePage's signups go to
 *   316_onepage_lead_magnets.sql             2026-10-28  onepage_leads lead magnet columns
 *   319_team_store_areas.sql                 2026-10-28  team members with OnePage read the store's products (needs part 135; skips itself without it)
 *   320_team_permissions.sql                 2026-10-28  store_team_members.permissions, onepage among them (needs part 135; skips itself without it)
 *   323_onepage_integrations_more_tools.sql  2026-10-28  onepage_integrations takes MailerLite, Brevo and Flodesk
 *   324_onepage_integration_sends.sql        2026-10-28  onepage_integration_sends: one row per tool and signup, so none is sent twice
 *   90_storage_policies_needs_owner.sql      2026-10-26  LAST: the storage.objects policies for every public bucket, avatars and onepage-assets among them (needs the owner of storage.objects)
 *   91_storage_policies_to_remove.sql        2026-10-26  read only: storage policies still to delete by name; empty when done
 */

/* ── Part 16_storage_buckets.sql (added 2026-10-26) ── */
/* Storage safety, buckets: paid file buckets private, picture buckets take pictures only, size limits. */
do $$ declare private_buckets text[] := array['digital-products', 'product-files', 'digital-assets']; image_types text[] := array['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif']; video_types text[] := array['video/mp4', 'video/webm', 'video/quicktime', 'video/x-m4v', 'video/mpeg', 'video/3gpp', 'video/ogg', 'video/x-matroska', 'video/avi', 'video/mov']; lead_types text[] := array['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif', 'video/*', 'audio/*', 'font/*', 'application/pdf', 'application/zip', 'application/x-zip-compressed', 'application/epub+zip', 'application/x-mobipocket-ebook', 'application/octet-stream', 'text/plain', 'text/csv', 'text/markdown', 'application/rtf', 'application/msword', 'application/vnd.ms-excel', 'application/vnd.ms-powerpoint', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'application/vnd.oasis.opendocument.text', 'application/vnd.oasis.opendocument.spreadsheet', 'application/vnd.rar', 'application/x-rar-compressed', 'application/x-7z-compressed', 'application/gzip', 'application/x-tar', 'application/json', 'image/vnd.adobe.photoshop', 'application/postscript', 'application/illustrator', 'model/stl', 'model/obj', 'model/gltf-binary', 'application/x-blender']; b text; begin foreach b in array private_buckets loop update storage.buckets set public = false where id = b; end loop; insert into storage.buckets (id, name, public) values ('digital-products', 'digital-products', false) on conflict (id) do update set public = false; foreach b in array array['product-images', 'avatars', 'covers', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'product-videos', 'email-images'] loop insert into storage.buckets (id, name, public) values (b, b, true) on conflict (id) do nothing; end loop; update storage.buckets set public = true, allowed_mime_types = image_types, file_size_limit = 26214400 where id in ('product-images', 'avatars', 'covers'); update storage.buckets set public = true, allowed_mime_types = image_types, file_size_limit = 5242880 where id = 'email-images'; update storage.buckets set public = true, allowed_mime_types = image_types || video_types where id in ('store-builder-images', 'onepage-assets', 'product-videos'); update storage.buckets set allowed_mime_types = lead_types where id in ('lead-form-files-v2', 'lead-form-files'); end; $$;

/* ── Part 18_storage_cleanup_functions.sql (added 2026-10-26) ── */
/* Storage cleanup: what no row refers to any more, and recent browser uploads for the metadata sweep. */
create or replace function public.storage_object_referenced(p_bucket text, p_name text) returns boolean language plpgsql stable security definer set search_path = public as $$ declare owner_key text := split_part(p_name, '/', 1); pattern text; v_creator uuid; v_user uuid; t record; q text; found boolean := false; skip text[] := array['rate_limit_hits', 'download_events', 'upload_events', 'product_views', 'product_analytics_daily', 'analytics_daily_rollups', 'security_events', 'email_events', 'email_logs', 'email_usage', 'ledger_events', 'seller_ledger', 'signup_attempts', 'site_web_vitals', 'blog_post_views', 'message_push_log', 'flow_execution_log', 'campaign_recipients', 'account_delete_codes', 'oauth_bridge_tokens', 'profile_username_history', 'username_history', 'website_address_history', 'admin_actions', 'admin_moderation_log']; begin if owner_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return true; end if; pattern := '%' || replace(replace(replace(p_name, '\', '\\'), '%', '\%'), '_', '\_') || '%'; select c.id, c.user_id into v_creator, v_user from public.creators c where c.id = owner_key::uuid or c.user_id = owner_key::uuid limit 1; if v_creator is null then v_user := owner_key::uuid; end if; if to_regclass('public.profiles') is not null then execute 'select exists (select 1 from public.profiles x where x.id = $1 and x::text like $2)' into found using v_user, pattern; if found then return true; end if; end if; for t in select c.table_name, c.column_name, (c.data_type = 'uuid') as is_uuid from information_schema.columns c join information_schema.tables tb on tb.table_schema = c.table_schema and tb.table_name = c.table_name where c.table_schema = 'public' and tb.table_type = 'BASE TABLE' and c.column_name in ('creator_id', 'owner_id', 'user_id', 'product_id', 'install_id', 'site_id') and not (c.table_name = any(skip)) order by c.table_name, c.column_name loop q := case when t.column_name = 'creator_id' and v_creator is not null then format('select exists (select 1 from public.%I x where x.creator_id%s = $1%s and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name in ('owner_id', 'user_id') and v_user is not null then format('select exists (select 1 from public.%I x where x.%I%s = $2%s and x::text like $3)', t.table_name, t.column_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'product_id' and v_creator is not null and to_regclass('public.products') is not null then format('select exists (select 1 from public.%I x join public.products p on p.id%s = x.product_id%s where p.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'install_id' and v_creator is not null and to_regclass('public.store_theme_installs') is not null then format('select exists (select 1 from public.%I x join public.store_theme_installs i on i.id%s = x.install_id%s where i.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) when t.column_name = 'site_id' and v_creator is not null and to_regclass('public.sites') is not null then format('select exists (select 1 from public.%I x join public.sites s on s.id%s = x.site_id%s where s.creator_id = $1 and x::text like $3)', t.table_name, case when t.is_uuid then '' else '::text' end, case when t.is_uuid then '' else '::text' end) else null end; continue when q is null; begin execute q into found using v_creator, v_user, pattern; exception when others then found := true; end; if found then return true; end if; end loop; return false; end; $$;
revoke all on function public.storage_object_referenced(text, text) from public, anon, authenticated;
grant execute on function public.storage_object_referenced(text, text) to service_role;
create or replace function public.storage_cleanup_candidates(p_limit integer default 200, p_image_from_days integer default 32) returns table (bucket_id text, name text, reason text) language plpgsql stable security definer set search_path = public, storage as $$ begin if to_regclass('public.digital_assets') is null or to_regclass('public.product_bundles') is null then return; end if; return query with imports as ( select o.bucket_id::text, o.name::text, 'theme-import'::text as reason, o.created_at from storage.objects o where o.bucket_id = 'digital-products' and o.name ~ '^[0-9a-fA-F-]{36}/theme-imports/[0-9a-fA-F-]{36}\.zip$' and o.created_at < now() - interval '1 day' order by o.created_at limit p_limit ), digital as ( select o.bucket_id::text, o.name::text, 'digital-orphan'::text, o.created_at from storage.objects o where o.bucket_id in ('digital-products', 'product-files') and (o.name like '%/digital-products/%' or o.name like 'products/%') and o.created_at < now() - interval '3 days' and not exists ( select 1 from public.digital_assets da where da.file_path in (o.name, o.bucket_id || '/' || o.name) ) and not exists ( select 1 from public.digital_assets da where da.file_path like '%://%' and position(o.name in da.file_path) > 0 ) order by o.created_at limit p_limit ), bundles as ( select o.bucket_id::text, o.name::text, 'bundle-orphan'::text, o.created_at from storage.objects o where o.bucket_id = 'digital-products' and o.name like '%/bundles/%.zip' and o.created_at < now() - interval '3 days' and not exists (select 1 from public.product_bundles pb where pb.zip_path = o.name) order by o.created_at limit p_limit ), descriptions as ( select o.bucket_id::text, o.name::text, 'description-image'::text, o.created_at from storage.objects o where o.bucket_id = 'product-images' and o.name like '%\_description\_%' escape '\' and o.created_at < now() - interval '14 days' and o.created_at > now() - make_interval(days => greatest(p_image_from_days, 15)) and not public.storage_object_referenced(o.bucket_id, o.name) order by o.created_at limit p_limit ), removed as ( select o.bucket_id::text, o.name::text, 'removed-image'::text, o.created_at from storage.objects o where o.bucket_id = 'product-images' and o.name ~ '^[0-9a-fA-F-]{36}/([0-9a-fA-F-]{36}|temp)/' and o.name not like '%\_description\_%' escape '\' and o.created_at < now() - interval '30 days' and o.created_at > now() - make_interval(days => greatest(p_image_from_days, 31)) and not public.storage_object_referenced(o.bucket_id, o.name) order by o.created_at limit p_limit ) select c.bucket_id, c.name, c.reason from ( select * from imports union all select * from digital union all select * from bundles union all select * from descriptions union all select * from removed ) c order by c.created_at limit p_limit; end; $$;
revoke all on function public.storage_cleanup_candidates(integer, integer) from public, anon, authenticated;
grant execute on function public.storage_cleanup_candidates(integer, integer) to service_role;
create or replace function public.storage_recent_public_images(p_since_minutes integer default 150, p_limit integer default 200) returns table (bucket_id text, name text, size bigint, mimetype text) language sql stable security definer set search_path = public, storage as $$ select o.bucket_id::text, o.name::text, coalesce((o.metadata->>'size')::bigint, 0), coalesce(o.metadata->>'mimetype', '') from storage.objects o where o.bucket_id in ('avatars', 'covers', 'product-images', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'product-videos') and o.created_at > now() - make_interval(mins => greatest(p_since_minutes, 1)) and lower(coalesce(o.metadata->>'mimetype', '')) in ('image/jpeg', 'image/jpg', 'image/png', 'image/webp') and coalesce((o.metadata->>'size')::bigint, 0) between 1 and 26214400 order by o.created_at limit greatest(p_limit, 1); $$;
revoke all on function public.storage_recent_public_images(integer, integer) from public, anon, authenticated;
grant execute on function public.storage_recent_public_images(integer, integer) to service_role;
notify pgrst, 'reload schema';

/* ── Part 25_analytics_speed.sql (added 2026-10-26) ── */
/* Analytics that load quickly: indexes in the order the reports read, and the counting done in the database (analytics_visit_tally, analytics_all_time), the server's alone. Source: supabase/migrations/20261002_analytics_report_speed.sql. */
CREATE INDEX IF NOT EXISTS idx_analytics_events_creator_type_time_id ON public.analytics_events (creator_id, event_type, created_at, id);
CREATE INDEX IF NOT EXISTS idx_analytics_events_product_type_time_id ON public.analytics_events (product_id, event_type, created_at, id) WHERE product_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_orders_product_time_id ON public.orders (product_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_onepage_views_page_time_id ON public.onepage_views (onepage_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_onepage_clicks_page_time_id ON public.onepage_clicks (onepage_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_onepage_leads_page_time_id ON public.onepage_leads (onepage_id, created_at, id);
CREATE OR REPLACE FUNCTION public.analytics_visit_tally( p_creator_id uuid, p_product_id uuid, p_time_zone text, p_cur_start bigint, p_cur_end bigint, p_prev_start bigint, p_prev_end bigint, p_cur_starts bigint[], p_prev_starts bigint[], p_detail boolean DEFAULT true ) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH bounds AS ( SELECT timestamptz 'epoch' + p_cur_start * interval '1 millisecond' AS cs, timestamptz 'epoch' + p_cur_end * interval '1 millisecond' AS ce, timestamptz 'epoch' + p_prev_start * interval '1 millisecond' AS ps, timestamptz 'epoch' + p_prev_end * interval '1 millisecond' AS pe, coalesce(cardinality(p_cur_starts), 0) AS n ), win AS ( SELECT 'cur'::text AS w, b.cs AS ws, b.ce AS we, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_cur_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) AS starts FROM bounds b UNION ALL SELECT 'prev'::text, b.ps, b.pe, ARRAY(SELECT timestamptz 'epoch' + x * interval '1 millisecond' FROM unnest(coalesce(p_prev_starts, '{}'::bigint[])) WITH ORDINALITY u(x, i) ORDER BY i) FROM bounds b ), raw AS ( SELECT e.id, e.created_at, e.session_id::text AS session_id, e.visitor_id::text AS visitor_id, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.created_at >= b.cs AND e.created_at < b.ce UNION ALL SELECT e.id, e.created_at, e.session_id::text, e.visitor_id::text, e.source_category, e.referrer_domain, e.utm_campaign, e.country_code, e.country_name, e.city, e.device_type, e.browser, e.os, e.page_url FROM public.analytics_events e, bounds b WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) AND e.created_at >= b.ps AND e.created_at < b.pe AND NOT (e.created_at >= b.cs AND e.created_at < b.ce) ), wrows AS ( SELECT w.w, r.id, r.created_at, CASE WHEN cardinality(w.starts) > 0 THEN width_bucket(r.created_at, w.starts) - 1 END AS bucket, (CASE WHEN coalesce(r.session_id, '') <> '' THEN 's:' || r.session_id WHEN coalesce(r.visitor_id, '') <> '' THEN 'v:' || r.visitor_id || ':' || ( floor(extract(epoch FROM r.created_at))::bigint - floor(extract(epoch FROM (r.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || r.id::text END) COLLATE "C" AS skey FROM raw r JOIN win w ON r.created_at >= w.ws AND r.created_at < w.we ), firsts AS ( SELECT DISTINCT ON (w, skey) w, skey, created_at, id, bucket FROM wrows ORDER BY w, skey, created_at, id ), ranked AS ( SELECT f.w, row_number() OVER (PARTITION BY f.w ORDER BY f.created_at, f.id) AS rank, r.source_category, r.referrer_domain, r.utm_campaign, r.country_code, r.country_name, r.city, r.device_type, r.browser, r.os, split_part(split_part(r.page_url, '#', 1), '?', 1) AS page_url FROM firsts f JOIN raw r ON r.id = f.id WHERE p_detail ), view_b AS (SELECT w, bucket, count(*) AS c FROM wrows GROUP BY w, bucket), session_b AS (SELECT w, bucket, count(*) AS c FROM firsts GROUP BY w, bucket), buckets AS ( SELECT w.w, coalesce((SELECT sum(v.c) FROM view_b v WHERE v.w = w.w), 0) AS views, coalesce((SELECT sum(s.c) FROM session_b s WHERE s.w = w.w), 0) AS sessions, coalesce((SELECT jsonb_agg(coalesce(v.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN view_b v ON v.w = w.w AND v.bucket = g.i), '[]'::jsonb) AS view_buckets, coalesce((SELECT jsonb_agg(coalesce(s.c, 0) ORDER BY g.i) FROM bounds b, generate_series(0, b.n - 1) g(i) LEFT JOIN session_b s ON s.w = w.w AND s.bucket = g.i), '[]'::jsonb) AS session_buckets FROM win w ), steps AS ( SELECT w.w, s.event_type, count(DISTINCT s.skey) AS c FROM ( SELECT e.event_type, e.created_at, (CASE WHEN coalesce(e.session_id::text, '') <> '' THEN 's:' || e.session_id::text WHEN coalesce(e.visitor_id::text, '') <> '' THEN 'v:' || e.visitor_id::text || ':' || ( floor(extract(epoch FROM e.created_at))::bigint - floor(extract(epoch FROM (e.created_at AT TIME ZONE p_time_zone)::time))::bigint )::text ELSE 'e:' || e.created_at::text END) COLLATE "C" AS skey FROM public.analytics_events e, bounds b WHERE p_detail AND e.creator_id = p_creator_id AND e.event_type IN ('buy_click', 'checkout_start') AND (p_product_id IS NULL OR e.product_id = p_product_id) AND ((e.created_at >= b.cs AND e.created_at < b.ce) OR (e.created_at >= b.ps AND e.created_at < b.pe)) ) s JOIN win w ON s.created_at >= w.ws AND s.created_at < w.we GROUP BY w.w, s.event_type ), grouped AS ( SELECT w, CASE WHEN GROUPING(source_category) = 0 THEN 'source' WHEN GROUPING(referrer_domain) = 0 THEN 'referrer' WHEN GROUPING(utm_campaign) = 0 THEN 'campaign' WHEN GROUPING(city) = 0 THEN 'city' WHEN GROUPING(country_code) = 0 THEN 'country' WHEN GROUPING(device_type) = 0 THEN 'device' WHEN GROUPING(browser) = 0 THEN 'browser' WHEN GROUPING(os) = 0 THEN 'os' ELSE 'page' END AS kind, CASE WHEN GROUPING(source_category) = 0 THEN jsonb_build_array(source_category) WHEN GROUPING(referrer_domain) = 0 THEN jsonb_build_array(referrer_domain) WHEN GROUPING(utm_campaign) = 0 THEN jsonb_build_array(utm_campaign) WHEN GROUPING(city) = 0 THEN jsonb_build_array(city, country_code, country_name) WHEN GROUPING(country_code) = 0 THEN jsonb_build_array(country_code, country_name) WHEN GROUPING(device_type) = 0 THEN jsonb_build_array(device_type) WHEN GROUPING(browser) = 0 THEN jsonb_build_array(browser) WHEN GROUPING(os) = 0 THEN jsonb_build_array(os) ELSE jsonb_build_array(page_url) END AS cols, count(*) AS n, min(rank) AS r FROM ranked GROUP BY w, GROUPING SETS ((source_category), (referrer_domain), (utm_campaign), (country_code, country_name), (city, country_code, country_name), (device_type), (browser), (os), (page_url)) ), groups AS ( SELECT w, jsonb_object_agg(kind, rows) AS groups FROM (SELECT w, kind, jsonb_agg(cols || jsonb_build_array(n, r) ORDER BY r) AS rows FROM grouped GROUP BY w, kind) k GROUP BY w ), tallies AS ( SELECT w.w, jsonb_build_object( 'views', bk.views, 'view_buckets', bk.view_buckets, 'sessions', bk.sessions, 'session_buckets', bk.session_buckets, 'steps', CASE WHEN p_detail THEN jsonb_build_object( 'buy', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'buy_click'), 0), 'checkout', coalesce((SELECT s.c FROM steps s WHERE s.w = w.w AND s.event_type = 'checkout_start'), 0) ) END, 'groups', CASE WHEN p_detail THEN coalesce((SELECT g.groups FROM groups g WHERE g.w = w.w), '{}'::jsonb) END ) AS t FROM win w JOIN buckets bk ON bk.w = w.w ) SELECT jsonb_object_agg(w, t) FROM tallies$fn$;
CREATE OR REPLACE FUNCTION public.analytics_all_time(p_creator_id uuid, p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $fn$WITH lines AS ( SELECT coalesce('s:' || nullif(o.stripe_session_id, ''), 'o:' || o.id::text) AS k, o.status, greatest(0, coalesce(o.amount_cents, 0))::bigint AS gross, CASE WHEN o.status = 'refunded' THEN CASE WHEN o.refund_amount_cents > 0 THEN least(o.refund_amount_cents, greatest(0, coalesce(o.amount_cents, 0))) ELSE greatest(0, coalesce(o.amount_cents, 0)) END ELSE 0 END::bigint AS refunded FROM public.orders o WHERE o.product_id IN (SELECT p.id FROM public.products p WHERE p.creator_id = p_creator_id) AND (p_product_id IS NULL OR o.product_id = p_product_id) ), payments AS ( SELECT k, bool_and(coalesce(status = 'failed', false)) AS all_failed, bool_or(coalesce(status = 'pending', false)) AS any_pending, bool_or(coalesce(status = 'disputed', false)) AS any_disputed, greatest(0, sum(gross) - sum(refunded)) AS net FROM lines GROUP BY k ) SELECT jsonb_build_object( 'views', ( SELECT count(*) FROM public.analytics_events e WHERE e.creator_id = p_creator_id AND e.event_type = 'view' AND (p_product_id IS NULL OR e.product_id = p_product_id) ), 'orders', (SELECT count(*) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed), 'sales_cents', (SELECT coalesce(sum(net), 0) FROM payments WHERE NOT all_failed AND NOT any_pending AND NOT any_disputed) )$fn$;
REVOKE ALL ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.analytics_all_time(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_visit_tally(uuid, uuid, text, bigint, bigint, bigint, bigint, bigint[], bigint[], boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.analytics_all_time(uuid, uuid) TO service_role;

/* ── Part 43_onepage_forget_deleted_product.sql (added 2026-10-26) ── */
/* A deleted product leaves the OnePage that named it. A OnePage product block keeps a copy of the product inside onepages.draft_blocks and published_blocks (its title, price, picture and address), so deleting the product left the row on the page with its picture and a button to a page that is now a 404. The live page reads the product row instead of the copy now (lib/onepage/live-products.ts), so a visitor is right with or without this part; this is what takes the block out of the creator's own editor, and out of the stored page, for good. One function that removes every mention of one product from a block array (groups included, and an email capture block keeps collecting addresses but stops offering the deleted file), a trigger that calls it when a product is deleted, and a one off pass over the pages that already hold a block for a product that is gone. Deletes no product, no order and no page: only blocks naming a product that no longer exists. Changes nothing where onepages is missing. Safe to run again: the second run finds nothing to change. */
CREATE OR REPLACE FUNCTION public.onepage_blocks_without_product(p_blocks jsonb, p_product_id text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $fn$ DECLARE v_out jsonb := '[]'::jsonb; v_block jsonb; v_data jsonb; BEGIN IF p_blocks IS NULL OR jsonb_typeof(p_blocks) <> 'array' OR coalesce(p_product_id, '') = '' THEN RETURN p_blocks; END IF; FOR v_block IN SELECT value FROM jsonb_array_elements(p_blocks) LOOP v_data := CASE WHEN jsonb_typeof(v_block -> 'data') = 'object' THEN v_block -> 'data' ELSE '{}'::jsonb END; IF v_block ->> 'type' = 'product' AND v_data ->> 'product_id' = p_product_id THEN CONTINUE; END IF; IF v_block ->> 'type' = 'email_capture' AND v_data ->> 'digital_product_id' = p_product_id THEN v_block := jsonb_set(v_block, '{data}', v_data || jsonb_build_object('enable_digital_product', false, 'digital_product_id', null::text, 'digital_product_title', null::text, 'digital_product_thumbnail', null::text, 'digital_product_file_url', null::text)); ELSIF v_block ->> 'type' = 'group' AND jsonb_typeof(v_data -> 'children') = 'array' THEN v_block := jsonb_set(v_block, '{data}', jsonb_set(v_data, '{children}', public.onepage_blocks_without_product(v_data -> 'children', p_product_id))); END IF; v_out := v_out || jsonb_build_array(v_block); END LOOP; RETURN v_out; END $fn$;
CREATE OR REPLACE FUNCTION public.onepages_forget_deleted_product() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE v_owner uuid; BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN OLD; END IF; SELECT c.user_id INTO v_owner FROM public.creators c WHERE c.id = OLD.creator_id; UPDATE public.onepages o SET draft_blocks = public.onepage_blocks_without_product(o.draft_blocks, OLD.id::text), published_blocks = public.onepage_blocks_without_product(o.published_blocks, OLD.id::text) WHERE (o.seller_id = OLD.creator_id OR o.creator_id = OLD.creator_id OR (v_owner IS NOT NULL AND o.owner_id = v_owner)) AND (coalesce(o.draft_blocks::text, '') LIKE '%' || OLD.id::text || '%' OR coalesce(o.published_blocks::text, '') LIKE '%' || OLD.id::text || '%'); RETURN OLD; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'onepages_forget_deleted_product skipped for %: %', OLD.id, SQLERRM; RETURN OLD; END $fn$;
DROP TRIGGER IF EXISTS onepages_forget_deleted_product ON public.products;
CREATE TRIGGER onepages_forget_deleted_product AFTER DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.onepages_forget_deleted_product();
DO $$ DECLARE r record; v_id text; BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN; END IF; FOR r IN SELECT o.id AS page_id, coalesce(o.draft_blocks::text, '') || coalesce(o.published_blocks::text, '') AS blob FROM public.onepages o LOOP FOR v_id IN SELECT DISTINCT m[1] FROM regexp_matches(r.blob, '"(?:product_id|digital_product_id)"[[:space:]]*:[[:space:]]*"([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})"', 'g') AS m LOOP IF NOT EXISTS (SELECT 1 FROM public.products p WHERE p.id = v_id::uuid) THEN UPDATE public.onepages o SET draft_blocks = public.onepage_blocks_without_product(o.draft_blocks, v_id), published_blocks = public.onepage_blocks_without_product(o.published_blocks, v_id) WHERE o.id = r.page_id; END IF; END LOOP; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.onepages_forget_deleted_product() FROM PUBLIC, anon, authenticated;
notify pgrst, 'reload schema';

/* ── Part 44_profile_identity_follows.sql (added 2026-10-26) ── */
/* The name and the photo have one home, and every copy of them follows it. profiles.display_name and profiles.avatar_url are the creator's name and face; the OnePage keeps a copy in its title, in the copy taken when it was published, and in the SEO card's Meta title, the creators row keeps two columns of its own, and the creator page keeps the store name and the header photo. None of them moved when the profile changed, so a creator who renamed themselves kept the old name in their page's tab title and the old picture as its icon until they republished. This adds a trigger that moves every copy that STILL HOLDS THE OLD VALUE (a title somebody typed is left alone) and never lets that work fail a profile save, plus a one off pass for the copies already stale. Run after nothing; needs only the profiles, onepages, creators and store_builder_configs tables. Until it runs, the app does the same work from its own routes (lib/account/profile-follow), which covers Settings, the storefront's Edit profile and the photo save. */
CREATE OR REPLACE FUNCTION public.storelib_provider_photo(url text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(btrim(url) ~* '^https?://(([a-z0-9-]+\.)*googleusercontent\.com/(a|a-)/|([a-z0-9-]+\.)*googleusercontent\.com/-[^/]+/AAAAAAAAAAI/|graph\.facebook\.com/(v[0-9.]+/)?[^/]+/picture([/?]|$)|platform-lookaside\.fbsbx\.com/platform/profilepic/|pbs\.twimg\.com/profile_images/|avatars\.githubusercontent\.com/|cdn\.discordapp\.com/avatars/|media(-exp[0-9])?\.licdn\.com/dms/image/[^?]*profile-displayphoto)', false) $$;
/* A copy follows only when it is still what the profile held: empty stays empty (it already falls back to the profile), anything else was chosen by somebody and stays. */
CREATE OR REPLACE FUNCTION public.storelib_follow_text(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN nullif(btrim(coalesce(stored, '')), '') IS NULL THEN stored WHEN nullif(btrim(coalesce(was, '')), '') IS NOT NULL AND lower(btrim(stored)) = lower(btrim(was)) THEN now_value ELSE stored END $$;
/* The same for a photo, with two differences: it follows only when it is exactly the address the profile held (two addresses that differ in case are two files), and the account picture a sign in provider sent (Google's /a/ address, not every picture on Google's servers) is never one somebody chose, so it follows whatever the profile now says, a removal included. A photo uploaded to the OnePage is its own file and is never touched. */
CREATE OR REPLACE FUNCTION public.storelib_follow_photo(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN nullif(btrim(coalesce(stored, '')), '') IS NULL THEN stored WHEN public.storelib_provider_photo(stored) THEN now_value WHEN nullif(btrim(coalesce(was, '')), '') IS NOT NULL AND btrim(stored) = btrim(was) THEN now_value ELSE stored END $$;
/* The creator page config: the store name it shows, and the header photo, which keeps '' to mean "show my initials". */
CREATE OR REPLACE FUNCTION public.storelib_follow_config(cfg jsonb, nb text, na text, pb text, pa text, nm boolean, pm boolean) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN jsonb_typeof(cfg) <> 'object' THEN cfg ELSE (SELECT CASE WHEN nm AND jsonb_typeof(c1->'globalSettings') = 'object' AND c1#>>'{globalSettings,storeName}' IS NOT NULL THEN jsonb_set(c1, '{globalSettings,storeName}', to_jsonb(coalesce(public.storelib_follow_text(c1#>>'{globalSettings,storeName}', nb, na), ''))) ELSE c1 END FROM (SELECT CASE WHEN pm AND jsonb_typeof(cfg->'headerSettings') = 'object' AND cfg#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(cfg, '{headerSettings,avatarUrl}', to_jsonb(coalesce(public.storelib_follow_photo(cfg#>>'{headerSettings,avatarUrl}', pb, pa), ''))) ELSE cfg END AS c1) s) END $$;
/* The trigger itself. Everything it writes is inside a block that swallows its own errors: a copy that did not move is a copy the next save moves, and a rename must never fail because of one. */
CREATE OR REPLACE FUNCTION public.profiles_identity_follows() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE nb text := nullif(btrim(coalesce(old.display_name, '')), ''); na text := nullif(btrim(coalesce(new.display_name, '')), ''); pb text := nullif(btrim(coalesce(old.avatar_url, '')), ''); pa text := nullif(btrim(coalesce(new.avatar_url, '')), ''); nm boolean; pm boolean; cid uuid; BEGIN nm := nb IS DISTINCT FROM na; pm := pb IS DISTINCT FROM pa; IF NOT nm AND NOT pm THEN RETURN new; END IF; BEGIN UPDATE public.onepages o SET title = CASE WHEN nm THEN public.storelib_follow_text(o.title, nb, na) ELSE o.title END, avatar_url = CASE WHEN pm THEN public.storelib_follow_photo(o.avatar_url, pb, pa) ELSE o.avatar_url END, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(jsonb_set(o.published_profile, '{title}', coalesce(to_jsonb(CASE WHEN nm THEN public.storelib_follow_text(o.published_profile->>'title', nb, na) ELSE o.published_profile->>'title' END), 'null'::jsonb)), '{avatar_url}', coalesce(to_jsonb(CASE WHEN pm THEN public.storelib_follow_photo(o.published_profile->>'avatar_url', pb, pa) ELSE o.published_profile->>'avatar_url' END), 'null'::jsonb)) ELSE o.published_profile END, settings = CASE WHEN nm AND jsonb_typeof(o.settings) = 'object' THEN jsonb_set(o.settings, '{seo_title}', coalesce(to_jsonb(public.storelib_follow_text(o.settings->>'seo_title', nb, na)), 'null'::jsonb)) ELSE o.settings END WHERE o.owner_id = new.id; UPDATE public.creators c SET display_name = CASE WHEN nm THEN public.storelib_follow_text(c.display_name, nb, na) ELSE c.display_name END, avatar_url = CASE WHEN pm THEN public.storelib_follow_photo(c.avatar_url, pb, pa) ELSE c.avatar_url END WHERE c.user_id = new.id RETURNING c.id INTO cid; IF cid IS NOT NULL THEN UPDATE public.store_builder_configs s SET draft_config = public.storelib_follow_config(s.draft_config, nb, na, pb, pa, nm, pm), published_config = public.storelib_follow_config(s.published_config, nb, na, pb, pa, nm, pm) WHERE s.creator_id = cid; END IF; EXCEPTION WHEN others THEN RAISE WARNING 'profiles_identity_follows skipped for %: %', new.id, sqlerrm; END; RETURN new; END $fn$;
DROP TRIGGER IF EXISTS profiles_identity_follows ON public.profiles;
CREATE TRIGGER profiles_identity_follows AFTER UPDATE OF display_name, avatar_url ON public.profiles FOR EACH ROW WHEN (old.display_name IS DISTINCT FROM new.display_name OR old.avatar_url IS DISTINCT FROM new.avatar_url) EXECUTE FUNCTION public.profiles_identity_follows();
/* One off, for the copies already stale. First: a picture a sign in provider sent, sitting in a OnePage row, goes back to whatever the profile says. This is the Google photo that kept coming back after it was deleted. */
UPDATE public.onepages o SET avatar_url = CASE WHEN public.storelib_provider_photo(o.avatar_url) THEN p.avatar_url ELSE o.avatar_url END, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' AND public.storelib_provider_photo(o.published_profile->>'avatar_url') THEN jsonb_set(o.published_profile, '{avatar_url}', coalesce(to_jsonb(p.avatar_url), 'null'::jsonb)) ELSE o.published_profile END FROM public.profiles p WHERE p.id = o.owner_id AND (public.storelib_provider_photo(o.avatar_url) OR public.storelib_provider_photo(o.published_profile->>'avatar_url'));
/* And in the creator page header, draft and published alike. */
UPDATE public.store_builder_configs s SET draft_config = CASE WHEN public.storelib_provider_photo(s.draft_config#>>'{headerSettings,avatarUrl}') THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN public.storelib_provider_photo(s.published_config#>>'{headerSettings,avatarUrl}') THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND (public.storelib_provider_photo(s.draft_config#>>'{headerSettings,avatarUrl}') OR public.storelib_provider_photo(s.published_config#>>'{headerSettings,avatarUrl}'));
/* Second: creators.display_name and creators.avatar_url are copies of the profile that nothing in the app edits, so they are made equal to it. */
UPDATE public.creators c SET display_name = p.display_name, avatar_url = p.avatar_url FROM public.profiles p WHERE p.id = c.user_id AND (c.display_name IS DISTINCT FROM p.display_name OR c.avatar_url IS DISTINCT FROM p.avatar_url);
/* Third: a Meta title that is only one of the page's own names again. The OnePage SEO card filled its box with the page name and saved what it was showing, so the page carried a second copy of the name that outranked everything the tab title read. It says nothing the page does not already say. */
UPDATE public.onepages o SET settings = jsonb_set(o.settings, '{seo_title}', 'null'::jsonb) FROM public.profiles p WHERE p.id = o.owner_id AND jsonb_typeof(o.settings) = 'object' AND nullif(btrim(coalesce(o.settings->>'seo_title', '')), '') IS NOT NULL AND lower(btrim(o.settings->>'seo_title')) IN (lower(btrim(coalesce(o.title, ''))), lower(btrim(coalesce(o.published_profile->>'title', ''))), lower(btrim(coalesce(p.display_name, ''))));
/* Fourth, and the only statement here that names one account: the OnePage this was reported from (storelib.com/lucadragoste) still showed the name the account was opened with in the phone's bottom bar, from before the trigger above existed, and there is no way to tell from the row alone which of its three name copies holds it. All three are pointed at the profile's name. The page name can be typed again in the OnePage editor at any moment, and from then on it is left alone. A second run changes nothing. */
UPDATE public.onepages o SET title = p.display_name, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(o.published_profile, '{title}', coalesce(to_jsonb(p.display_name), 'null'::jsonb)) ELSE o.published_profile END, settings = CASE WHEN jsonb_typeof(o.settings) = 'object' THEN jsonb_set(o.settings, '{seo_title}', 'null'::jsonb) ELSE o.settings END FROM public.profiles p WHERE p.id = o.owner_id AND lower(coalesce(p.username, '')) = 'lucadragoste' AND (o.title IS DISTINCT FROM p.display_name OR o.published_profile->>'title' IS DISTINCT FROM p.display_name OR nullif(btrim(coalesce(o.settings->>'seo_title', '')), '') IS NOT NULL);
notify pgrst, 'reload schema';

/* ── Part 53_one_profile_photo.sql (added 2026-10-26) ── */
/* One profile photo, everywhere. profiles.avatar_url is the creator's face and every other row keeps a copy of it: onepages.avatar_url and the copy taken when the page was published, creators.avatar_url, and the creator page header's avatarUrl in store_builder_configs and product_page_configs. Part 44 moved a copy only while it still held the value the profile used to hold, so the first editor to write a copy made it 'chosen' and it never followed again: one owner had three different faces at once, one on his creator page, one in Settings and one on his OnePage. A name can honestly differ from page to page; a face cannot. This makes every copy of the PHOTO take whatever the profile says, leaves the name rule exactly as it was, and brings the copies already apart back onto one photo. An account whose profile has no photo but whose pages do, and which never chose or removed a photo itself, keeps that face: it is lifted into the profile first. Run after part 44, whose trigger and helpers it reuses. Adds no table and grants nothing. Until it runs, the app does the same work from its own routes (lib/account/profile-follow), which covers Settings, the OnePage editor, the creator page builder, the storefront's Edit profile and both onboarding flows. */
/* The photo half of part 44's follow, replaced by a mirror: a copy takes the profile's photo whatever it holds. Part 44's storelib_follow_config and its trigger both call this, so replacing it here changes every copy the trigger writes without touching the name rule (storelib_follow_text), which still leaves a page title somebody typed alone. */
CREATE OR REPLACE FUNCTION public.storelib_follow_photo(stored text, was text, now_value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT now_value $$;
/* The trigger again, in case part 44's was dropped by hand; skipped when part 44 has not run, because its function is what the trigger calls. */
DO $do$ BEGIN IF to_regprocedure('public.profiles_identity_follows()') IS NOT NULL THEN DROP TRIGGER IF EXISTS profiles_identity_follows ON public.profiles; CREATE TRIGGER profiles_identity_follows AFTER UPDATE OF display_name, avatar_url ON public.profiles FOR EACH ROW WHEN (old.display_name IS DISTINCT FROM new.display_name OR old.avatar_url IS DISTINCT FROM new.avatar_url) EXECUTE FUNCTION public.profiles_identity_follows(); END IF; END $do$;
/* Part 44's test for the account picture a sign in provider sent, again, word for word, so this part stands on its own where part 44 has not run. Replacing it with the same body changes nothing where it has. */
CREATE OR REPLACE FUNCTION public.storelib_provider_photo(url text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(btrim(url) ~* '^https?://(([a-z0-9-]+\.)*googleusercontent\.com/(a|a-)/|([a-z0-9-]+\.)*googleusercontent\.com/-[^/]+/AAAAAAAAAAI/|graph\.facebook\.com/(v[0-9.]+/)?[^/]+/picture([/?]|$)|platform-lookaside\.fbsbx\.com/platform/profilepic/|pbs\.twimg\.com/profile_images/|avatars\.githubusercontent\.com/|cdn\.discordapp\.com/avatars/|media(-exp[0-9])?\.licdn\.com/dms/image/[^?]*profile-displayphoto)', false) $$;
/* The best face an account already has outside its profile: the creator page header first, because onboarding writes it and the creator page shows it, then the OnePage's. A picture a sign in provider sent is not one anybody chose and is passed over. */
CREATE OR REPLACE FUNCTION public.storelib_best_photo(uid uuid) RETURNS text LANGUAGE sql STABLE AS $$ SELECT q.photo FROM (SELECT coalesce(nullif(btrim(coalesce((SELECT s.published_config#>>'{headerSettings,avatarUrl}' FROM public.store_builder_configs s JOIN public.creators c ON c.id = s.creator_id WHERE c.user_id = uid AND s.page_type = 'shop' LIMIT 1), '')), ''), nullif(btrim(coalesce((SELECT s.draft_config#>>'{headerSettings,avatarUrl}' FROM public.store_builder_configs s JOIN public.creators c ON c.id = s.creator_id WHERE c.user_id = uid AND s.page_type = 'shop' LIMIT 1), '')), ''), nullif(btrim(coalesce((SELECT o.avatar_url FROM public.onepages o WHERE o.owner_id = uid LIMIT 1), '')), '')) AS photo) q WHERE q.photo IS NOT NULL AND NOT public.storelib_provider_photo(q.photo) $$;
/* An account with no photo in its profile and a face on its pages keeps that face, rather than losing it to the mirror below. Only for an account that never chose or removed a photo itself: the mark the app keeps on the account (storelib_avatar_chosen, lib/account/avatar) is what stops a photo somebody deleted in Settings being lifted back in from a leftover copy. */
UPDATE public.profiles p SET avatar_url = public.storelib_best_photo(p.id) WHERE nullif(btrim(coalesce(p.avatar_url, '')), '') IS NULL AND public.storelib_best_photo(p.id) IS NOT NULL AND NOT coalesce((SELECT u.raw_user_meta_data->>'storelib_avatar_chosen' = 'true' FROM auth.users u WHERE u.id = p.id), false);
/* The OnePage: its own copy and the copy taken at the last publish, which is what the live page, the tab icon and the share card are built from. */
UPDATE public.onepages o SET avatar_url = p.avatar_url, published_profile = CASE WHEN jsonb_typeof(o.published_profile) = 'object' THEN jsonb_set(o.published_profile, '{avatar_url}', coalesce(to_jsonb(p.avatar_url), 'null'::jsonb)) ELSE o.published_profile END FROM public.profiles p WHERE p.id = o.owner_id AND (o.avatar_url IS DISTINCT FROM p.avatar_url OR (jsonb_typeof(o.published_profile) = 'object' AND o.published_profile->>'avatar_url' IS DISTINCT FROM p.avatar_url));
/* The creator row, which the product page and the website's name read. */
UPDATE public.creators c SET avatar_url = p.avatar_url FROM public.profiles p WHERE p.id = c.user_id AND c.avatar_url IS DISTINCT FROM p.avatar_url;
/* The creator page header, draft and published alike. A header that never kept a photo of its own already draws the profile's and is left absent; '' is the creator page's way of saying 'show my initials', which is what a profile with no photo means. */
UPDATE public.store_builder_configs s SET draft_config = CASE WHEN s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND ((s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.draft_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')) OR (s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.published_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')));
/* And a product page's own header, where that table exists. */
DO $do$ BEGIN IF to_regclass('public.product_page_configs') IS NOT NULL THEN EXECUTE $q$ UPDATE public.product_page_configs s SET draft_config = CASE WHEN s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.draft_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.draft_config END, published_config = CASE WHEN s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL THEN jsonb_set(s.published_config, '{headerSettings,avatarUrl}', to_jsonb(coalesce(p.avatar_url, ''))) ELSE s.published_config END FROM public.creators c JOIN public.profiles p ON p.id = c.user_id WHERE c.id = s.creator_id AND ((s.draft_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.draft_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, '')) OR (s.published_config#>>'{headerSettings,avatarUrl}' IS NOT NULL AND s.published_config#>>'{headerSettings,avatarUrl}' IS DISTINCT FROM coalesce(p.avatar_url, ''))) $q$; END IF; END $do$;
notify pgrst, 'reload schema';

/* ── Part 54_onepage_address_any_case.sql (added 2026-10-26) ── */
/* One OnePage address in any case. A OnePage is served at storelib.me/{address}, and storelib.me sends /Mara to /mara, so two pages whose addresses differ only in case (Mara and mara) would be one address with two owners. The app already refuses a new address that another page holds in any case (lib/onepage/name-availability); this is the database's own guard for two saves at the same moment: a unique index on lower(slug), so the second save fails and the editor says the address is taken. Made only when no two pages already share an address in different case; otherwise it skips itself with a warning naming the query to see them, and changes nothing. Changes no row. Nothing where there is no onepages table. Needs nothing else. Until it runs, addresses are checked by the app as before. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 54: there is no onepages table, nothing to do.'; ELSIF EXISTS (SELECT 1 FROM public.onepages WHERE slug IS NOT NULL GROUP BY lower(slug) HAVING count(*) > 1) THEN RAISE WARNING 'part 54 skipped: two OnePages share an address in different case, so the one address in any case index was not made. See them with: select lower(slug), array_agg(slug), array_agg(id) from public.onepages where slug is not null group by 1 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX IF NOT EXISTS onepages_slug_lower_unique ON public.onepages (lower(slug)); END IF; END $$;
notify pgrst, 'reload schema';

/* ── Part 57_onepage_share_image.sql (added 2026-10-26) ── */
/* The picture a shared OnePage link shows. A OnePage shared in a chat or on social media shows its creator's profile photo by default, as a Linktree or Beacons link does; in the editor (Settings, SEO) the creator can choose the share card Storelib draws from the page, or a picture of their own, and go back to the photo. Adds one column, onepages.share_image_mode: 'profile', 'card' or 'custom', 'profile' unless changed, with a check that it is one of the three. The first run sets every OnePage already there to 'profile', as the owner asked, a choice kept in a page's settings before this ran included; a second run changes nothing, so a choice made after the first run is kept. Nothing where there is no onepages table. Needs nothing else. Until it runs, every page shows its profile photo and a choice made in the editor is kept in the page's settings. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 57: there is no onepages table, nothing to do.'; ELSIF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'share_image_mode') THEN ALTER TABLE public.onepages ADD COLUMN share_image_mode text NOT NULL DEFAULT 'profile'; UPDATE public.onepages SET share_image_mode = 'profile' WHERE share_image_mode IS DISTINCT FROM 'profile'; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name = 'settings' AND data_type = 'jsonb') THEN UPDATE public.onepages SET settings = settings - 'share_image_mode' WHERE settings -> 'share_image_mode' IS NOT NULL; END IF; END IF; END $$;
DO $$ BEGIN IF to_regclass('public.onepages') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('public.onepages') AND conname = 'onepages_share_image_mode_check') THEN ALTER TABLE public.onepages ADD CONSTRAINT onepages_share_image_mode_check CHECK (share_image_mode IN ('profile', 'card', 'custom')); END IF; END $$;
notify pgrst, 'reload schema';

/* ── Part 58_onepage_old_addresses.sql (added 2026-10-26) ── */
/* Old OnePage addresses keep working. A OnePage is served at storelib.me/{address}, and a creator can change that address in the editor; the old one then answered 404, although it may already be in a bio, a QR code or a post. This keeps each address a page leaves behind in a new table, onepage_slug_history, written by a trigger on onepages when the address changes (lower case, the page's id, when), and the page and the old links (lib/onepage/resolve-address.ts) send a visitor from an old address to the one the page has now, with a permanent redirect. An address another page holds now is always that page's. Server only: row level security on and no policy, so only the service role reads it. The trigger never stops a save: if it cannot write, it warns and the save goes on. Changes no row. Nothing where there is no onepages table. Needs nothing else. Until it runs, a page's old address is not followed, as before; a creator's old username is followed either way. */
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 58: there is no onepages table, nothing to do.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.onepage_slug_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), onepage_id uuid NOT NULL REFERENCES public.onepages(id) ON DELETE CASCADE, old_slug text NOT NULL, new_slug text, changed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS onepage_slug_history_old_slug_idx ON public.onepage_slug_history (old_slug, changed_at DESC); ALTER TABLE public.onepage_slug_history ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.onepage_slug_history FROM anon, authenticated; END $$;
CREATE OR REPLACE FUNCTION public.onepages_keep_old_slug() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN IF OLD.slug IS NOT NULL AND btrim(OLD.slug) <> '' AND lower(OLD.slug) IS DISTINCT FROM lower(NEW.slug) THEN INSERT INTO public.onepage_slug_history (onepage_id, old_slug, new_slug) VALUES (OLD.id, lower(btrim(OLD.slug)), lower(btrim(NEW.slug))); END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'onepages_keep_old_slug skipped for %: %', OLD.id, SQLERRM; RETURN NEW; END $fn$;
REVOKE ALL ON FUNCTION public.onepages_keep_old_slug() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RETURN; END IF; DROP TRIGGER IF EXISTS onepages_keep_old_slug ON public.onepages; CREATE TRIGGER onepages_keep_old_slug AFTER UPDATE OF slug ON public.onepages FOR EACH ROW EXECUTE FUNCTION public.onepages_keep_old_slug(); END $$;
notify pgrst, 'reload schema';

/* ── Part 70_public_upload_safety.sql (added 2026-10-26) ── */
/* The public buckets a browser writes into directly get a size ceiling, and the hourly file pass gets a list of what landed in them. A signed upload URL cannot limit what is sent through it, so a page could ask for "freebie.pdf, 1 KB" and PUT half a gigabyte: `lead-form-files-v2` (link page lead magnets), `product-videos`, `onepage-assets` and `store-builder-images` had no file_size_limit at all, and now they have the one their kind of file needs. Also adds storage_recent_public_objects, which lists what was written into those buckets lately and is NOT a picture the metadata pass already reads, so /api/cron/strip-image-metadata can check videos, lead magnets and anything else the same way it checks pictures (lib/security/uploads/direct.ts). Server only: the function is revoked from anon and authenticated and granted to the service role. Changes no rows in any table; only bucket settings, and only where they were empty or larger. Needs nothing else, and is safe to run twice. Until it runs, uploads and downloads work the same and the hourly pass reads pictures only, as before. */
DO $do$ BEGIN IF to_regclass('storage.buckets') IS NULL THEN RAISE NOTICE 'part 70: there is no storage.buckets here, nothing to set.'; RETURN; END IF; UPDATE storage.buckets SET file_size_limit = 1073741824 WHERE id IN ('lead-form-files-v2', 'lead-form-files') AND (file_size_limit IS NULL OR file_size_limit > 1073741824); UPDATE storage.buckets SET file_size_limit = 2000000000 WHERE id IN ('product-videos', 'onepage-assets', 'store-builder-images') AND (file_size_limit IS NULL OR file_size_limit > 2000000000); END $do$;
CREATE OR REPLACE FUNCTION public.storage_recent_public_objects(p_since_minutes integer DEFAULT 150, p_limit integer DEFAULT 200) RETURNS TABLE (bucket_id text, name text, size bigint, mimetype text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, storage AS $fn$ SELECT o.bucket_id::text, o.name::text, coalesce((o.metadata->>'size')::bigint, 0), coalesce(o.metadata->>'mimetype', '') FROM storage.objects o WHERE o.bucket_id IN ('avatars', 'covers', 'product-images', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'product-videos') AND o.created_at > now() - make_interval(mins => greatest(p_since_minutes, 1)) AND NOT (lower(coalesce(o.metadata->>'mimetype', '')) IN ('image/jpeg', 'image/jpg', 'image/png', 'image/webp') AND coalesce((o.metadata->>'size')::bigint, 0) BETWEEN 1 AND 26214400) ORDER BY o.created_at LIMIT greatest(p_limit, 1); $fn$;
REVOKE ALL ON FUNCTION public.storage_recent_public_objects(integer, integer) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.storage_recent_public_objects(integer, integer) TO service_role;
notify pgrst, 'reload schema';

/* ── Part 165_columns_production_has.sql (added 2026-10-26) ── */
/* Columns production has that no file here ever created, so a database built from this repository matches it. They were made in the Supabase dashboard before the repository kept SQL, and the app has read and written them since: creators.support_email (Settings > Store details' contact email, where receipts and seller emails reply to), profiles.welcome_completed (signup and onboarding), the Address card's profiles.address_line1, address_line2, city, state, postal_code, country and the payout form's first_name, last_name, onepages.seller_id (whose store a OnePage subscribes to) and products.inventory_count (a counted product's stock, read by the shop's lists). Each is added only where it is missing, nullable, with no default except welcome_completed's false, so no existing row changes. onepages is skipped where that table is not there. Then the column grants part 63 keeps are applied again (storelib_share_public_columns), as they were when these columns already existed in production. Needs nothing else. Safe to run again. */
ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS support_email text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS welcome_completed boolean DEFAULT false;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS first_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS last_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address_line1 text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address_line2 text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS city text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS state text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS postal_code text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS country text;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS inventory_count integer;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'onepages.seller_id skipped: public.onepages does not exist here'; RETURN; END IF; ALTER TABLE public.onepages ADD COLUMN IF NOT EXISTS seller_id uuid; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
notify pgrst, 'reload schema';

/* ── Part 281_onepage_leads_country.sql (added 2026-10-26) ── */
/* OnePage signups keep the visitor's country. /api/onepage/leads has written country_code and country_name on public.onepage_leads since January (the country on OnePage analytics), but no SQL file in this repository creates them: the table was made by hand. This adds them only where they are missing, so a database without them stops depending on the route's fallback (it saves the signup without the country). No row changes. Does nothing if public.onepage_leads does not exist. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_leads') IS NOT NULL THEN ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS country_code text; ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS country_name text; END IF; END $do$;
notify pgrst, 'reload schema';

/* ── Part 282_onepage_media_uploads.sql (added 2026-10-26) ── */
/* OnePage pictures and videos upload (round 11): the onepage-assets bucket (profile photo and video, logo, wallpaper picture and video, link thumbnails, image blocks) takes a video up to 2 GB (at least 2147483648 bytes, so a file a phone calls "2 GB" fits; a higher limit already set is kept) and every type the editor sends: JPEG, PNG, WebP, GIF, AVIF, MP4, MOV (video/quicktime), WebM and M4V (video/x-m4v). Types it already allowed stay allowed; a bucket that allows every type (no list) is left that way. The editor now sends large files by TUS resumable upload with the signed in person's own session, which needs the same four owner-folder policies part 90 makes ("storelib owner ... public buckets"); this creates any of the four that is missing, exactly as part 90 writes them, and if the SQL editor's role may not create storage policies it says so in a NOTICE and changes nothing there (part 90 or README Route 1 does it then). NOT SQL: the project's own upload limit caps every bucket and is 50 MB until raised: Supabase dashboard > Storage > Settings > "Upload file size limit", set it to 2 GB (Pro plan or above). Safe to run again. */
DO $do$ DECLARE needed text[] := array['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif', 'video/mp4', 'video/quicktime', 'video/webm', 'video/x-m4v']; BEGIN IF to_regclass('storage.buckets') IS NULL THEN RAISE NOTICE 'part 282: there is no storage.buckets here, nothing to set.'; RETURN; END IF; INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('onepage-assets', 'onepage-assets', true, 2147483648, needed) ON CONFLICT (id) DO NOTHING; UPDATE storage.buckets SET public = true, file_size_limit = greatest(coalesce(file_size_limit, 0), 2147483648), allowed_mime_types = CASE WHEN allowed_mime_types IS NULL THEN NULL ELSE array(SELECT DISTINCT t FROM unnest(allowed_mime_types || needed) AS t ORDER BY t) END WHERE id = 'onepage-assets' AND (public IS DISTINCT FROM true OR file_size_limit IS NULL OR file_size_limit < 2147483648 OR (allowed_mime_types IS NOT NULL AND NOT allowed_mime_types @> needed)); END $do$;
DO $do$ DECLARE public_list text := '''product-images'', ''avatars'', ''covers'', ''store-builder-images'', ''onepage-assets'', ''lead-form-files-v2'', ''lead-form-files'', ''product-videos'', ''email-images'''; owner_expr text; BEGIN IF to_regclass('storage.objects') IS NULL THEN RAISE NOTICE 'part 282: there is no storage.objects here, no policies to check.'; RETURN; END IF; IF to_regprocedure('public.storage_owns_path(text)') IS NULL THEN RAISE NOTICE 'part 282: public.storage_owns_path is missing; run part 15 first, then this again.'; RETURN; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'storage' AND table_name = 'objects' AND column_name = 'owner_id') THEN owner_expr := 'owner_id = (select auth.uid())::text'; ELSE owner_expr := 'owner = (select auth.uid())'; END IF; BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner read public buckets') THEN EXECUTE format('create policy %I on storage.objects for select to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner read public buckets', public_list, owner_expr); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner insert public buckets') THEN EXECUTE format('create policy %I on storage.objects for insert to authenticated with check (bucket_id = any (array[%s]) and public.storage_owns_path(name))', 'storelib owner insert public buckets', public_list); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner update public buckets') THEN EXECUTE format('create policy %I on storage.objects for update to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s)) with check (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner update public buckets', public_list, owner_expr, public_list, owner_expr); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'storelib owner delete public buckets') THEN EXECUTE format('create policy %I on storage.objects for delete to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner delete public buckets', public_list, owner_expr); END IF; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'part 282: this role may not create storage policies (%). Uploads use the owner-folder policies part 90 makes: run part 90, or README Route 1.', SQLERRM; END; END $do$;
notify pgrst, 'reload schema';

/* ── Part 315_onepage_integrations.sql (added 2026-10-28) ── */
/* The tools a OnePage's signups are sent to as they happen (round 40): new `onepage_integrations`, one row per store and tool (Mailchimp, Kit, beehiiv, Zapier, Make, Google Sheets or a webhook of the creator's own), holding the chosen list or form (`config`), the API key or the webhook address and signing secret sealed by the server (`secret_ciphertext`, AES-256-GCM, never readable by a browser), and what happened to the signups sent (`sent_count`, `failed_count`, `last_sent_at`, `last_error`, `last_error_at`). Written and read only by the server for the signed in owner (/api/onepage/integrations) and by the signup routes (lib/onepage/integrations/deliver-server): row level security on, nothing granted to anon or authenticated, so no key can be read from a browser even by its owner. `onepage_integration_note` counts one send in one step, so two signups at once both count; only the service role may run it. New table and function only; no existing row changes. Until it runs, the editor's Settings › Integrations says this part is needed and signups are kept on Storelib as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.onepage_integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('mailchimp', 'kit', 'beehiiv', 'zapier', 'make', 'sheets', 'webhook')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'paused')), account_label text CHECK (account_label IS NULL OR length(account_label) <= 200), config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object'), secret_ciphertext text CHECK (secret_ciphertext IS NULL OR secret_ciphertext LIKE 'v1.%'), sent_count integer NOT NULL DEFAULT 0 CHECK (sent_count >= 0), failed_count integer NOT NULL DEFAULT 0 CHECK (failed_count >= 0), last_sent_at timestamptz, last_error text CHECK (last_error IS NULL OR length(last_error) <= 500), last_error_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT onepage_integrations_one_per_tool UNIQUE (creator_id, provider));
CREATE INDEX IF NOT EXISTS onepage_integrations_connected_idx ON public.onepage_integrations (creator_id) WHERE status = 'connected';
ALTER TABLE public.onepage_integrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.onepage_integrations FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.onepage_integrations TO service_role;
CREATE OR REPLACE FUNCTION public.onepage_integration_note(p_id uuid, p_ok boolean, p_error text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $fn$ UPDATE public.onepage_integrations SET sent_count = sent_count + CASE WHEN p_ok THEN 1 ELSE 0 END, failed_count = failed_count + CASE WHEN p_ok THEN 0 ELSE 1 END, last_sent_at = CASE WHEN p_ok THEN now() ELSE last_sent_at END, last_error = CASE WHEN p_ok THEN NULL ELSE left(coalesce(p_error, 'Not sent.'), 500) END, last_error_at = CASE WHEN p_ok THEN NULL ELSE now() END, updated_at = now() WHERE id = p_id; $fn$;
REVOKE ALL ON FUNCTION public.onepage_integration_note(uuid, boolean, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.onepage_integration_note(uuid, boolean, text) TO service_role;
notify pgrst, 'reload schema';

/* ── Part 316_onepage_lead_magnets.sql (added 2026-10-28) ── */
/* What a OnePage signup was for (round 40): `onepage_leads` takes `magnet_kind` (download, discount or waitlist, from the new lead magnet block; empty for the email signup) and `magnet_label` (the waitlist's name, or the discount's "15% off"; never the code), written by /api/onepage/lead-magnet, so Leads can tell a waitlist from a newsletter. Two new columns, empty by default; no row changes. Until it runs the route keeps the lead without them. Does nothing if public.onepage_leads does not exist. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_leads') IS NULL THEN RAISE NOTICE 'part 316: onepage_leads is not here; nothing to do.'; RETURN; END IF; ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS magnet_kind text; ALTER TABLE public.onepage_leads ADD COLUMN IF NOT EXISTS magnet_label text; ALTER TABLE public.onepage_leads DROP CONSTRAINT IF EXISTS onepage_leads_magnet_kind_check; ALTER TABLE public.onepage_leads ADD CONSTRAINT onepage_leads_magnet_kind_check CHECK (magnet_kind IS NULL OR magnet_kind IN ('download', 'discount', 'waitlist')) NOT VALID; ALTER TABLE public.onepage_leads DROP CONSTRAINT IF EXISTS onepage_leads_magnet_label_len; ALTER TABLE public.onepage_leads ADD CONSTRAINT onepage_leads_magnet_label_len CHECK (magnet_label IS NULL OR length(magnet_label) <= 200) NOT VALID; END $do$;
DO $do$ BEGIN IF to_regclass('public.onepage_leads') IS NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS onepage_leads_magnet_idx ON public.onepage_leads (onepage_id, magnet_kind, created_at DESC) WHERE magnet_kind IS NOT NULL; END $do$;
notify pgrst, 'reload schema';

/* ── Part 319_team_store_areas.sql (added 2026-10-28) ── */
/* The team in the OnePage and the community (round 40, run after part 135; before or after part 320): two functions that answer, inside a row level security policy, whether the signed in person is on a store's team with a permission. public.team_store_ids(area) returns the stores (creators.id) where the signed in account is an active member whose permissions hold that area; public.team_can(store, area) answers for one store. Both read store_team_members.permissions through to_jsonb, so they work before part 320 has added the column (and then answer no, as a row from before part 320 holds no area but Orders) and need nothing run again after it. Both are security definer, answer only for auth.uid() (never for a visitor), and only for the twelve area keys. One policy uses them: "storelib team reads store products", so the OnePage editor's product picker, opened by a team member with OnePage, lists the store's products, drafts too, as it does for the owner. It only adds reading; nothing is written through it and nothing changes for the owner or for visitors. The OnePage's own reads and writes go through the server with the member's permissions checked on each request (lib/team/onepage.ts), and the communities are server only already (lib/communities/server/team.ts). Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 319: store_team_members is not here yet; run part 135 first, then this again.'; RETURN; END IF; EXECUTE $f$create or replace function public.team_store_ids(p_area text) returns setof uuid language sql stable security definer set search_path = public as $b$ select m.creator_id from public.store_team_members m where (select auth.uid()) is not null and m.user_id = (select auth.uid()) and m.status = 'active' and p_area = any (array['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts_billing']) and coalesce(to_jsonb(m) -> 'permissions', '[]'::jsonb) ? p_area $b$$f$; EXECUTE $f$create or replace function public.team_can(p_creator uuid, p_area text) returns boolean language sql stable security definer set search_path = public as $b$ select p_creator is not null and exists (select 1 from public.team_store_ids(p_area) s where s = p_creator) $b$$f$; COMMENT ON FUNCTION public.team_store_ids(text) IS 'The stores where the signed in account is an active team member holding this area (store_team_members.permissions, part 320). For row level security policies (part 319).'; COMMENT ON FUNCTION public.team_can(uuid, text) IS 'Whether the signed in account is an active team member of this store holding this area (part 319).'; REVOKE ALL ON FUNCTION public.team_store_ids(text) FROM PUBLIC, anon; REVOKE ALL ON FUNCTION public.team_can(uuid, text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.team_store_ids(text) TO authenticated, service_role; GRANT EXECUTE ON FUNCTION public.team_can(uuid, text) TO authenticated, service_role; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 319: there is no products table here, no policy to add.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'products' AND policyname = 'storelib team reads store products') THEN CREATE POLICY "storelib team reads store products" ON public.products FOR SELECT TO authenticated USING (creator_id IN (SELECT public.team_store_ids('onepage'))); END IF; END $do$;
notify pgrst, 'reload schema';

/* ── Part 320_team_permissions.sql (added 2026-10-28) ── */
/* Team permissions, like Shopify's staff permissions (round 40, run after part 135): each person on a store's team gets their own list of what they may do, in a new column `store_team_members.permissions` (text[], from website, onepage, creator_pages, products, orders, customers, marketing, community, analytics, settings, team, payouts_billing), chosen in Settings > Team from a preset (Full access, Content editor, Support) or ticked one by one, and changed there later. Everyone already on a team keeps exactly what they could use before: a Manager gets orders, Staff (never open to invite) gets nothing; the old role column stays as it is. A row the app writes without the column reads as its role, so nothing breaks while an older server is still running. The table stays server only: row level security on, no policy, nothing granted to anon or signed in users; every page and route checks the member's permissions on the server on each request (lib/team/server requireTeamPermission). Until it runs, Settings > Team can only give Orders and says permissions are not set up for anything else. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 320: store_team_members is not here yet; run part 135 first, then this again.'; RETURN; END IF; ALTER TABLE public.store_team_members ADD COLUMN IF NOT EXISTS permissions text[]; UPDATE public.store_team_members SET permissions = CASE WHEN role = 'manager' THEN ARRAY['orders']::text[] ELSE '{}'::text[] END WHERE permissions IS NULL; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_team_members_permissions_check' AND conrelid = 'public.store_team_members'::regclass) THEN ALTER TABLE public.store_team_members ADD CONSTRAINT store_team_members_permissions_check CHECK (permissions IS NULL OR (permissions <@ ARRAY['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts_billing']::text[] AND cardinality(permissions) <= 12)); END IF; COMMENT ON COLUMN public.store_team_members.permissions IS 'What this member may do in the store (lib/team/permissions.ts). NULL: read as the role (manager: orders).'; ALTER TABLE public.store_team_members ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_team_members FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_team_members TO service_role; END $do$;
notify pgrst, 'reload schema';

/* ── Part 323_onepage_integrations_more_tools.sql (added 2026-10-28) ── */
/* MailerLite, Brevo and Flodesk for a OnePage's signups (round 41, run after `315`): the `onepage_integrations` provider check takes 'mailerlite', 'brevo' and 'flodesk' beside Mailchimp, Kit, beehiiv, Zapier, Make, Google Sheets and a webhook. The check made by part 315 (named onepage_integrations_provider_check by Postgres) is dropped and added again NOT VALID, then validated, so the table is never locked against writes while old rows are read; every row already there holds one of the old seven and passes. One constraint changes; no row, column, grant or policy does. Until it runs, connecting one of the three says this part is needed and the other tools work as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_integrations') IS NULL THEN RAISE NOTICE 'part 323: run part 315 first.'; RETURN; END IF; ALTER TABLE public.onepage_integrations DROP CONSTRAINT IF EXISTS onepage_integrations_provider_check; ALTER TABLE public.onepage_integrations ADD CONSTRAINT onepage_integrations_provider_check CHECK (provider IN ('mailchimp', 'kit', 'beehiiv', 'mailerlite', 'brevo', 'flodesk', 'zapier', 'make', 'sheets', 'webhook')) NOT VALID; ALTER TABLE public.onepage_integrations VALIDATE CONSTRAINT onepage_integrations_provider_check; END $do$;
notify pgrst, 'reload schema';

/* ── Part 324_onepage_integration_sends.sql (added 2026-10-28) ── */
/* One OnePage signup, one delivery to each tool (round 41, run after `315`): new `onepage_integration_sends`, one row per connected tool (`integration_id`, deleted with it) and signup (`send_key`, a SHA-256 of the address, the form and the block, so it holds no address), written by the server just before a signup is sent (lib/onepage/integrations/deliver-server) and removed again when the send did not go. The same person signing up on the same block again is then not a second Zapier run, a second Make scenario or a second Google Sheets row. Row level security on, nothing granted to anon or authenticated; only the service role reads or writes it. New table only; no existing row changes. Until it runs, every signup is sent as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_integrations') IS NULL THEN RAISE NOTICE 'part 324: run part 315 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.onepage_integration_sends (integration_id uuid NOT NULL REFERENCES public.onepage_integrations(id) ON DELETE CASCADE, send_key text NOT NULL CHECK (send_key ~ '^[0-9a-f]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (integration_id, send_key)); ALTER TABLE public.onepage_integration_sends ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.onepage_integration_sends FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, DELETE ON public.onepage_integration_sends TO service_role; END $do$;
notify pgrst, 'reload schema';

/* ── Part 90_storage_policies_needs_owner.sql (added 2026-10-26) ── */
/* LAST, ON ITS OWN. Replaces the storage.objects policies. Needs the owner of storage.objects; see README if it says "must be owner". */
do $$ declare private_buckets text[] := array['digital-products', 'product-files', 'digital-assets']; public_buckets text[] := array['product-images', 'avatars', 'covers', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'lead-form-files', 'product-videos', 'email-images']; managed text[]; public_list text; owner_expr text; pol record; b text; mentions text; unmanaged text; begin managed := private_buckets || public_buckets; select string_agg(quote_literal(x), ', ') into public_list from unnest(public_buckets) as x; if exists (select 1 from information_schema.columns where table_schema = 'storage' and table_name = 'objects' and column_name = 'owner_id') then owner_expr := 'owner_id = (select auth.uid())::text'; else owner_expr := 'owner = (select auth.uid())'; end if; for pol in select policyname, roles, cmd, coalesce(qual, '') || ' ' || coalesce(with_check, '') as body from pg_policies where schemaname = 'storage' and tablename = 'objects' loop continue when pol.roles <@ array['service_role']::name[]; continue when pol.policyname like 'storelib owner %'; mentions := null; foreach b in array managed loop if position(quote_literal(b) in pol.body) > 0 then mentions := b; exit; end if; end loop; if mentions is not null or position('bucket_id' in pol.body) = 0 then select string_agg(distinct m[1], ', ') into unmanaged from regexp_matches(pol.body, '''([^'']+)''::text', 'g') as m where not (m[1] = any(managed)) and exists (select 1 from storage.buckets sb where sb.id = m[1]); execute format('drop policy %I on storage.objects', pol.policyname); raise notice 'dropped storage policy "%" (%, roles %)%', pol.policyname, pol.cmd, pol.roles, case when unmanaged is not null then ' - it also named: ' || unmanaged || ', check those buckets still work' else '' end; end if; end loop; for pol in select policyname from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner %' loop execute format('drop policy %I on storage.objects', pol.policyname); end loop; execute format( 'create policy %I on storage.objects for select to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner read public buckets', public_list, owner_expr); execute format( 'create policy %I on storage.objects for insert to authenticated with check (bucket_id = any (array[%s]) and public.storage_owns_path(name))', 'storelib owner insert public buckets', public_list); execute format( 'create policy %I on storage.objects for update to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s)) with check (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner update public buckets', public_list, owner_expr, public_list, owner_expr); execute format( 'create policy %I on storage.objects for delete to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner delete public buckets', public_list, owner_expr); create policy "storelib owner reserved read digital-products" on storage.objects for select to authenticated using (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)); create policy "storelib owner reserved insert digital-products" on storage.objects for insert to authenticated with check (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)); create policy "storelib owner reserved update digital-products" on storage.objects for update to authenticated using (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)) with check (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)); end; $$;

/* ── Part 91_storage_policies_to_remove.sql (added 2026-10-26) ── */
/* Read only. Only for the dashboard route in README: the storage policies to delete by name. Empty when done. */
select p.policyname as delete_this_policy, p.cmd, p.roles, p.qual, p.with_check from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and not (p.roles <@ array['service_role']::name[]) and ((p.policyname like 'storelib owner %' and not (p.policyname like any (array['storelib owner read public buckets%', 'storelib owner insert public buckets%', 'storelib owner update public buckets%', 'storelib owner delete public buckets%', 'storelib owner reserved read digital-products%', 'storelib owner reserved insert digital-products%', 'storelib owner reserved update digital-products%']))) or (p.policyname not like 'storelib owner %' and (exists (select 1 from unnest(array['digital-products', 'product-files', 'digital-assets', 'product-images', 'avatars', 'covers', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'lead-form-files', 'product-videos', 'email-images']) as mb where position(quote_literal(mb) in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) > 0) or position('bucket_id' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0))) order by p.policyname;

